// Извлечение текста договора
const userId = $json.user_id;
const extractedText = $json.data.extracted_text;

// Проверка на пустой текст
if (!extractedText || extractedText.trim().length === 0) {
  throw new Error('Текст договора пуст');
}

return {
  json: {
    userId,
    contractText: extractedText,
  }
}

// Загрузка промпта для анализа
const fs = require('fs');
const path = require('path');

const promptPath = path.join('/app/prompts', 'contract-reviewer', 'analysis.txt');
let prompt = fs.readFileSync(promptPath, 'utf8');

// Замена плейсхолдера
prompt = prompt.replace('{{CONTRACT_TEXT}}', $json.contractText);

return {
  json: {
    userId: $json.userId,
    contractText: $json.contractText,
    prompt,
  }
}

// Парсинг JSON ответа от AI
const content = $json.content;

try {
  // Попытка распарсить JSON
  const analysisResult = JSON.parse(content);

  // Валидация структуры
  if (!analysisResult.risks || !Array.isArray(analysisResult.risks)) {
    throw new Error('Неверная структура ответа: отсутствует risks');
  }

  // Определение общего уровня риска
  let overallRisk = 'low';
  const severities = analysisResult.risks.map(r => r.severity);

  if (severities.includes('critical')) {
    overallRisk = 'critical';
  } else if (severities.includes('high')) {
    overallRisk = 'high';
  } else if (severities.includes('medium')) {
    overallRisk = 'medium';
  }

  return {
    json: {
      userId: $json.userId,
      analysis: {
        summary: analysisResult.summary || 'Анализ завершён',
        risk_level: overallRisk,
        risks: analysisResult.risks,
        recommendations: analysisResult.recommendations || [],
      },
      tokensUsed: $json.usage?.total_tokens || 0,
      timestamp: new Date().toISOString(),
    }
  };
} catch (error) {
  // Если не удалось распарсить JSON, создаём структуру вручную
  return {
    json: {
      userId: $json.userId,
      analysis: {
        summary: 'Анализ завершён',
        risk_level: 'medium',
        risks: [],
        recommendations: ['Рекомендуется ручная проверка договора'],
      },
      tokensUsed: $json.usage?.total_tokens || 0,
      timestamp: new Date().toISOString(),
      rawContent: content,
    }
  };
}

// Форматирование финального ответа
const response = {
  contract_review_id: require('uuid').v4(),
  status: 'completed',
  analysis: $json.analysis,
  tokens_used: $json.tokensUsed,
  created_at: $json.timestamp,
};

return {
  json: response
}
